class HttpHost{
  constructor(options){this.options=options;this.info={transport:'real-loopback-http',hiddenConsole:true,noBrowser:true,noWebview:true,forcedStop:false};this.logs={};for(const name of ['broker.stdout.jsonl','broker.stderr.log'])this.logs[name]=fs.openSync(path.join(options.out,name),'wx');
    this.child=spawn(options.python,['-I','-B',path.join(ROOT,ORACLE),'http-broker','--binary',options.binary,'--assets',options.assets,'--profile',options.profile,'--documents',options.documents,'--out',options.out,'--port',String(options.port)],{windowsHide:true,stdio:['pipe','pipe','pipe'],env:systemEnvironment(options.profile,options.documents)});this.info.brokerPid=this.child.pid;this.child.on('error',error=>{this.spawnError=error;});this.child.stdin.on('error',error=>{this.stdinError=error;});this.closed=new Promise(resolve=>{this.child.once('close',(code,signal)=>{this.exit={code,signal};resolve();});});this.child.stdout.on('data',chunk=>fs.writeSync(this.logs['broker.stdout.jsonl'],chunk));this.child.stderr.on('data',chunk=>fs.writeSync(this.logs['broker.stderr.log'],chunk));this.origin='http://127.0.0.1:'+options.port;}
  async ready(){await until(async()=>{assert(!this.exit,'HTTP broker exited during startup');const response=await requestHttp(this.origin,'GET','/api/convert/progress?job=owned-nonexistent');assert.equal(response.status,404);assert.equal(response.body.error_code,'job_not_found');return true;},'headless loopback host readiness');}
  async stop(){if(this.stopPromise)return this.stopPromise;this.stopPromise=(async()=>{this.child.stdin.end('shutdown\n');const ended=await Promise.race([this.closed.then(()=>true),delay(25000).then(()=>false)]);if(!ended){this.info.forcedStop=true;this.child.kill();await Promise.race([this.closed,delay(5000)]);}for(const fd of Object.values(this.logs))fs.closeSync(fd);const file=path.join(this.options.out,'broker-report.json');assert(fs.existsSync(file),'HTTP broker failed to record owned cleanup');const result=JSON.parse(fs.readFileSync(file,'utf8')),forcedStop=this.info.forcedStop||result.forcedStop;this.info={...this.info,...result,forcedStop};assert.equal(this.info.forcedStop,false);assert.equal(result.passed,true,'HTTP broker did not exit cleanly');assert.equal(result.hostExitCode,0);assert.equal(result.instanceRemoved,true);assert.equal(this.exit?.code,0);return this.info;})();return this.stopPromise;}
}

